INSERT INTO "pipelines" ("id", "name", "description", "stages") VALUES ('set-up-test-targets', 'Set up test targets', 'Reads a Project''s repository and proposes its test targets, for the user to apply; changes no file.', '[{"kind":"agent","key":"set-up-test-targets","name":"Set up test targets","duty":"onboards-projects","brief":"Read the repository''s manifests and their scripts, its Gradle files and wrapper, its own start and build scripts and .devcontainer/, and change no file. Name only the entry points spec 2.12 allows: a file in the repository with its arguments, a script the package manifest lists, a Gradle task through the repository''s wrapper, or a .devcontainer/ service (Hosted only); never a command line or inline shell. End with propose_test_targets, giving every target at once.","session":"fresh","budget":100000,"optional":false,"routes":[{"to":null,"condition":null}],"place":{"column":0,"row":0}}]'::jsonb) ON CONFLICT DO NOTHING;--> statement-breakpoint
